invalid:
data = {"a": 1}
for _key, value in data.items():
    print(value)

corrected:
data = {"a": 1}
for value in data.values():
    print(value)

invalid:
def example(flag):
    if flag:
        print(flag)
        return None
    print(1)

corrected:
def example(flag):
    if flag:
        print(flag)
        return
    print(1)

invalid:
def example(values):
    used, unused = values
    return used

corrected:
def example(values):
    used, _unused = values
    return used

invalid:
def example(first, second):
    if first:
        if second:
            print(1)

corrected:
def example(first, second):
    if first and second:
        print(1)

invalid:
def example(value):
    if value == 1:
        print(value)
    elif value == 2:
        print(value)

